/**
 * Tests for lib/transcript-context — measured context occupancy.
 *
 * These run against REAL files on disk, not an fs mock. The whole point of
 * this module is that it reads a shape CC actually writes, so a mock that
 * returns a hand-built shape would reproduce the closed loop #3321 is about.
 * The fixtures below use the literal `usage` block observed in a live 2.1.228
 * transcript.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, writeFileSync, rmSync, chmodSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { readMeasuredContextTokens } from '../../lib/transcript-context.js';

let dir: string;

/** Shape copied from a real transcript line, trimmed to the read fields. */
function assistantLine(
  usage: Record<string, unknown>,
  extra: Record<string, unknown> = {},
): string {
  return JSON.stringify({
    type: 'assistant',
    isSidechain: false,
    uuid: 'u-1',
    timestamp: '2026-08-12T00:00:00.000Z',
    message: { role: 'assistant', content: [], usage },
    ...extra,
  });
}

function userLine(): string {
  return JSON.stringify({
    type: 'user',
    isSidechain: false,
    message: { role: 'user', content: 'hi' },
  });
}

function write(name: string, lines: string[]): string {
  const p = join(dir, name);
  writeFileSync(p, `${lines.join('\n')}\n`, 'utf8');
  return p;
}

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'ork-transcript-ctx-'));
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

describe('readMeasuredContextTokens', () => {
  it('sums input + cache_creation + cache_read from the last assistant turn', () => {
    const p = write('t.jsonl', [
      userLine(),
      assistantLine({
        input_tokens: 2,
        cache_creation_input_tokens: 2179,
        cache_read_input_tokens: 302_054,
        output_tokens: 111,
      }),
    ]);
    // The observed live values: 2 + 2179 + 302054 = 304,235.
    expect(readMeasuredContextTokens(p)).toBe(304_235);
  });

  it('excludes output_tokens — occupancy is the prompt, not the reply', () => {
    const p = write('t.jsonl', [
      assistantLine({ input_tokens: 10, output_tokens: 5000 }),
    ]);
    expect(readMeasuredContextTokens(p)).toBe(10);
  });

  it('takes the LAST assistant turn, not the first', () => {
    const p = write('t.jsonl', [
      assistantLine({ cache_read_input_tokens: 1000 }),
      userLine(),
      assistantLine({ cache_read_input_tokens: 250_000 }),
    ]);
    expect(readMeasuredContextTokens(p)).toBe(250_000);
  });

  it('skips sidechain turns — a subagent context is not the session context', () => {
    const p = write('t.jsonl', [
      assistantLine({ cache_read_input_tokens: 180_000 }),
      assistantLine({ cache_read_input_tokens: 9 }, { isSidechain: true }),
    ]);
    expect(readMeasuredContextTokens(p)).toBe(180_000);
  });

  it('skips assistant turns carrying no usage block', () => {
    const p = write('t.jsonl', [
      assistantLine({ cache_read_input_tokens: 42_000 }),
      JSON.stringify({ type: 'assistant', message: { content: [] } }),
    ]);
    expect(readMeasuredContextTokens(p)).toBe(42_000);
  });

  it('survives unparseable lines around a good one', () => {
    const p = write('t.jsonl', [
      assistantLine({ cache_read_input_tokens: 7_000 }),
      '{ this is not json',
      '',
    ]);
    expect(readMeasuredContextTokens(p)).toBe(7_000);
  });

  it('finds the last entry in a multi-megabyte transcript', () => {
    // Bigger than the 256KB tail window, so this also proves the read is
    // anchored to the END of the file rather than the start.
    const filler = JSON.stringify({
      type: 'user',
      message: { role: 'user', content: 'x'.repeat(20_000) },
    });
    const lines = Array.from({ length: 200 }, () => filler);
    lines.push(assistantLine({ input_tokens: 3, cache_read_input_tokens: 512_000 }));
    const p = write('big.jsonl', lines);
    expect(readMeasuredContextTokens(p)).toBe(512_003);
  });

  it('returns null (never 0) when nothing usable is present', () => {
    expect(readMeasuredContextTokens(write('empty.jsonl', []))).toBeNull();
    expect(readMeasuredContextTokens(write('users.jsonl', [userLine()]))).toBeNull();
    expect(
      readMeasuredContextTokens(write('zeros.jsonl', [assistantLine({ input_tokens: 0 })])),
    ).toBeNull();
  });

  it('returns null for a missing path or no path at all', () => {
    expect(readMeasuredContextTokens(undefined)).toBeNull();
    expect(readMeasuredContextTokens(join(dir, 'nope.jsonl'))).toBeNull();
  });

  it('returns null rather than throwing on an unreadable file', () => {
    const p = write('locked.jsonl', [assistantLine({ input_tokens: 5 })]);
    chmodSync(p, 0o000);
    try {
      expect(readMeasuredContextTokens(p)).toBeNull();
    } finally {
      chmodSync(p, 0o644);
    }
  });

  it('coerces non-numeric usage fields to zero instead of NaN', () => {
    const p = write('t.jsonl', [
      assistantLine({ input_tokens: 'lots', cache_read_input_tokens: 100 }),
    ]);
    expect(readMeasuredContextTokens(p)).toBe(100);
  });
});
